CREATE TABLE "SupplierCheck" ("id" UUID NOT NULL, "paymentId" UUID NOT NULL, "checkNumber" TEXT, "bank" TEXT, "branch" TEXT, "amount" BIGINT NOT NULL, "dueDate" DATE NOT NULL, "status" "CheckStatus" NOT NULL DEFAULT 'pending', "clearedAt" TIMESTAMPTZ, "bouncedAt" TIMESTAMPTZ, CONSTRAINT "SupplierCheck_pkey" PRIMARY KEY ("id"), CONSTRAINT "SupplierCheck_paymentId_key" UNIQUE ("paymentId"), CONSTRAINT "SupplierCheck_paymentId_fkey" FOREIGN KEY ("paymentId") REFERENCES "supplier_payments"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "SupplierCheck_dueDate_status_idx" ON "SupplierCheck"("dueDate", "status");